relay.content_template:
@echo off
setlocal DisableDelayedExpansion
set /p ENGRAM_ROOT=<"%~dp0{root_file}"
if exist "%ENGRAM_ROOT%\engram.cmd" goto :launch
if exist "%ENGRAM_ROOT%\Engram.exe" goto :launch
set /p ENGRAM_ROOT=<"%~dp0{physroot_file}"
:launch
cd /d "%ENGRAM_ROOT%" || goto :fail
if exist ".\Engram.exe" (
    ".\Engram.exe" open "%~1"
    exit /b %ERRORLEVEL%
)
if exist ".\engram.cmd" (
    call ".\engram.cmd" open "%~1"
    exit /b %ERRORLEVEL%
)
if exist ".\_sys\start.bat" (
    call ".\_sys\start.bat" "%~1"
    exit /b %ERRORLEVEL%
)
:fail
echo [Error] Engram root not found: %ENGRAM_ROOT%
exit /b 1
